#!/bin/bash
# ============================================================================
# fix_surgery_dashboard_recovery_episodes_shape.sh
#
# Fixes: "(a.recovery_episodes || []).some is not a function" error on the
# Surgery Dashboard's Active tab.
#
# ROOT CAUSE: recovery_episodes.ot_schedule_id has a UNIQUE constraint in
# the database, making it a genuine 1:1 relationship with ot_schedule --
# not 1:many. PostgREST therefore embeds recovery_episodes as a single
# object (or null) when queried from the ot_schedule side, never as an
# array. getSurgeryDashboardActive (in doctor-dashboard-surgery/actions.js)
# incorrectly assumed an array and called .some()/.find() on it, which
# throws the moment any ot_schedule row with status='Completed' actually
# has a recovery episode attached (confirmed against your training data,
# which currently has 6 such cases).
#
# FIX: recovery_episodes is now treated as the single object/null it
# actually is -- no .some()/.find(), just a direct property check.
#
#   MODIFIED: app/(main)/doctor-dashboard-surgery/actions.js
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Surgery Dashboard recovery_episodes shape fix"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

if [ ! -f "app/(main)/doctor-dashboard-surgery/actions.js" ]; then
  echo "ERROR: app/(main)/doctor-dashboard-surgery/actions.js not found."
  echo "This script expects the Surgery Dashboard to already exist."
  exit 1
fi

echo "==> Overwriting app/(main)/doctor-dashboard-surgery/actions.js"
echo "" | base64 -d > "app/(main)/doctor-dashboard-surgery/actions.js"

echo ""
echo "==> File written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Fix Surgery Dashboard: recovery_episodes is a 1:1 object, not an array"'
echo "    git push"
